module traffic_light(
    input rst_n, input clk, input pass_request,
    output [7:0] clock, output red, yellow, green
);
// Add your code here
reg [7:0]cnt;
reg [1:0]state;
reg p_red, p_yellow, p_green;
assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;
localparam idle = 2'b00;
localparam s1_red = 2'b01;
localparam s2_yellow = 2'b10;
localparam s3_green = 2'b11;
always@(*) begin
    case(state)
        idle: begin
            state <= s1_red;
            p_red <= 1'd0;
            p_yellow <= 1'd0;
            p_green <= 1'd0;
        end 
        s1_red:begin
            if(cnt == 8'd3) begin
                state <= s3_green;
                p_red <= 1'd0;
            end else begin
                state <= s1_red;
                p_red <= 1'd1;
            end
        end 
        s2_yellow:begin
            if(cnt == 8'd3) begin
                state <= s1_red;
                p_yellow <= 1'd0;
            end else begin
                state <= s2_yellow;
                p_yellow <= 1'd1;
            end
        end 
        s3_green:begin
            if(cnt == 8'd3) begin
                state <= s2_yellow;
                p_green <= 1'd0;
            end else begin
                state <= s3_green;
                p_green <= 1'd1;
            end
        end
        default :begin
            state <= idle;
            p_red <= 1'd0;
            p_yellow <= 1'd0;
            p_green <= 1'd0;
        end
    endcase
end
always@(posedge clk,negedge rst_n)begin
    if(!rst_n)begin
        cnt <= 8'd10;
    end else if(pass_request && green && (cnt > 10)) begin
        cnt <= 8'd10;
    end else if(!green && p_green)begin
        cnt <= 8'd60;
    end else if(!yellow && p_yellow)begin
        cnt <= 8'd5;
    end else if(!red && p_red)begin
        cnt <= 8'd10;
    end else begin
        cnt <= cnt - 8'd1;
    end
end
assign clock = cnt;
endmodule
